  'dash.settings.autonomous_confirm': '자동 모드로 전환하시겠습니까?\n\n이 설정은 모든 도구 카테고리 — bash, Git, file_write, file_edit, database_query, 브라우저, http_request — 를 자동으로 승인하며, 파괴적 하위 집합 (rm, 포맷, 삭제, 덮어쓰기) 도 포함됩니다. 여전히 프롬프트가 표시되는 유일한 작업은 되돌릴 수 없는 패턴 (force-push, hard reset, 히스토리 재작성, 패키지 게시, git_commit --amend) 입니다. 이러한 작업은 영구적으로 승인이 필요합니다.\n\n긴 세션 동안 확인 없이 Ava 가 작동하도록 하려면 선택하세요. 단, Git 을 통해 잘못된 쓰기 작업을 복구할 수 있는 워크스페이스에서만 사용하세요.',
